# Let me search for potential grid separators
h, w = len(grid), len(grid[0])

# Check for full horizontal separators (full row of same color)
print("Checking for full row separators:")
for r in range(h):
    row_values = set(grid[r])
    if len(row_values) == 1:
        print(f"  Full row at row {r} with color {list(row_values)[0]}")

# Check rows where ALL values are 9 (background)
print("\nEmpty rows (all 9s):")
for r in range(h):
    if all(grid[r][c] == 9 for c in range(w)):
        print(f"  Row {r}")

# Check for full column separators
print("\nChecking for full column separators:")
for c in range(w):
    col_values = [grid[r][c] for r in range(h)]
    if len(set(col_values)) == 1:
        print(f"  Full col at col {c} with color {col_values[0]}")

# Check columns where ALL values are 9
print("\nEmpty columns (all 9s):")
for c in range(w):
    if all(grid[r][c] == 9 for r in range(h)):
        print(f"  Col {c}")

# Let me check for full rows/cols of color 4 (the feature color)
h, w = len(grid), len(grid[0])

print("Checking for full horizontal rows of 4s:")
for r in range(h):
    if all(grid[r][c] == 4 for c in range(w)):
        print(f"  Row {r} is all 4s")

print("\nChecking for full vertical columns of 4s:")
for c in range(w):
    if all(grid[r][c] == 4 for r in range(h)):
        print(f"  Col {c} is all 4s")

# Let me also look for more partial patterns like:
# - Runs of 4s in a column (vertical segments)
# - Runs of 4s in a row (horizontal segments)
print("\nLongest run of consecutive 4s in each column:")
for c in range(w):
    consecutive = 0
    max_consecutive = 0
    for r in range(h):
        if grid[r][c] == 4:
            consecutive += 1
            if max_consecutive < consecutive:
                max_consecutive = consecutive
    if max_consecutive >= 3:
        print(f"  Col {c}: max consecutive 4s = {max_consecutive} at rows {r for r in range(h) if grid[r][c]==4}")

